/* @autogenerated */
package net.civeira.phylax.feature.observe.slo;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;

import io.quarkus.arc.Arc;
import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.metric.MetricDeriver;
import net.civeira.phylax.feature.observe.metric.MetricPoint;
import net.civeira.phylax.feature.observe.metric.ObserveMetrics;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSlo;
import net.civeira.phylax.feature.observe.observedslo.domain.gateway.ObservedSloFilter;
import net.civeira.phylax.feature.observe.observedslo.domain.gateway.ObservedSloQueryRepositoryGateway;
import net.civeira.phylax.feature.observe.source.SourceRegistry;

/**
 * Evaluates the enabled objectives every minute on the RED metrics and keeps the result in memory
 * for the viewer and the slo-burn alert rules: compliance and remaining budget of the window, and
 * the burn rate in 5 min, 30 min, 1 h and 6 h.
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class SloEvaluator {

  private static final long MINUTE = MetricDeriver.MINUTE;
  private static final long HOUR = MetricDeriver.HOUR;

  /**
   * State of an objective.
   *
   * @param compliance share of good requests of the window (null without requests)
   * @param budget remaining error budget of the window (1 untouched, 0 spent, negative over)
   */
  public record SloStatus(String uid, String name, String originUid, String source, String route,
      String kind, double objective, int windowDays, long good, long total, Double compliance,
      double budget, double burn5m, double burn30m, double burn1h, double burn6h, boolean fastBurn,
      boolean slowBurn) {}

  private final ObservedSloQueryRepositoryGateway slos;
  private final ObserveMetrics metrics;
  private final SourceRegistry registry;

  private volatile List<SloStatus> current = List.of();

  public List<SloStatus> current() {
    return current;
  }

  /** Called by the minute scheduler, outside any request. */
  public void evaluate() {
    boolean activated = !Arc.container().requestContext().isActive();
    if (activated) {
      Arc.container().requestContext().activate();
    }
    try {
      List<ObservedSlo> enabled = slos.list(ObservedSloFilter.builder().build()).stream()
          .filter(slo -> Boolean.TRUE.equals(slo.isEnabled())).toList();
      List<SloStatus> result = new ArrayList<>();
      long now = System.currentTimeMillis();
      for (ObservedSlo slo : enabled) {
        try {
          result.add(status(slo, now));
        } catch (RuntimeException ex) {
          log.warn("Unable to evaluate the objective {}: {}", slo.getName(), ex.getMessage());
        }
      }
      current = result;
    } finally {
      if (activated) {
        Arc.container().requestContext().terminate();
      }
    }
  }

  private SloStatus status(final ObservedSlo slo, final long now) {
    String originUid = slo.getOriginUid();
    String code = registry.all().stream().filter(source -> originUid.equals(source.uid()))
        .map(SourceRegistry.Source::code).findFirst().orElse(originUid);
    String kind =
        null == slo.getKind() ? "availability" : slo.getKind().name().toLowerCase(Locale.ROOT);
    Integer latency = "latency".equals(kind) ? slo.getLatencyMs().orElse(500) : null;
    double objective =
        Math.max(0, Math.min(999.9, null == slo.getObjective() ? 995 : slo.getObjective()))
            / 1000.0;
    int days = null == slo.getWindowDays() || slo.getWindowDays() <= 0 ? 30 : slo.getWindowDays();
    String route = slo.getRoute().orElse(null);
    Set<String> sources = Set.of(code);
    List<MetricPoint> window = metrics.raw(sources, now - days * 24 * HOUR, now, true);
    List<MetricPoint> recent = metrics.raw(sources, now - 6 * HOUR, now, false);
    SloMath.Counts total = SloMath.counts(window, route, latency, now - days * 24 * HOUR, now);
    double burn5m =
        SloMath.burn(SloMath.counts(recent, route, latency, now - 5 * MINUTE, now), objective);
    double burn30m =
        SloMath.burn(SloMath.counts(recent, route, latency, now - 30 * MINUTE, now), objective);
    double burn1h =
        SloMath.burn(SloMath.counts(recent, route, latency, now - HOUR, now), objective);
    double burn6h =
        SloMath.burn(SloMath.counts(recent, route, latency, now - 6 * HOUR, now), objective);
    return new SloStatus(slo.getUid(), slo.getName(), originUid, code, route, kind, objective, days,
        total.good(), total.total(),
        total.total() == 0 ? null : (double) total.good() / total.total(),
        SloMath.budgetRemaining(total, objective), burn5m, burn30m, burn1h, burn6h,
        burn1h > SloMath.FAST_BURN && burn5m > SloMath.FAST_BURN,
        burn6h > SloMath.SLOW_BURN && burn30m > SloMath.SLOW_BURN);
  }
}
